  const MemberExpr *ME = dyn_cast<MemberExpr>(EE);
  if (!ME)
    return nullptr;

  const FieldDecl *FD = dyn_cast<FieldDecl>(ME->getMemberDecl());
  if (!FD)
    return nullptr;

