// From the FAM field, obtain its counter field via CountedByAttr
const FieldDecl *SAGenTestChecker::getCounterFieldFromFAM(const FieldDecl *FAMFD) {
  if (!FAMFD)
    return nullptr;

  const CountedByAttr *A = FAMFD->getAttr<CountedByAttr>();
  if (!A)
    return nullptr;

  // Clang 18 stores the counted_by argument as an expression (getCount()),
  // not as an IdentifierInfo. Resolve the referenced field via the
  // DeclRefExpr, falling back to its identifier spelling when the reference
  // is not resolved.
  const Expr *CountE = A->getCount();
  if (!CountE)
    return nullptr;
  CountE = CountE->IgnoreParenImpCasts();

  const auto *DRE = dyn_cast<DeclRefExpr>(CountE);
  if (!DRE)
    return nullptr;

  if (const FieldDecl *CountFD = dyn_cast<FieldDecl>(DRE->getDecl()))
    return CountFD;

  const IdentifierInfo *CounterII = DRE->getNameInfo().getIdentifier();
  if (!CounterII)
    return nullptr;

  const RecordDecl *RD = FAMFD->getParent();
  if (!RD)
    return nullptr;

  for (const FieldDecl *F : RD->fields())
    if (F->getIdentifier() == CounterII)
      return F;

  return nullptr;
}

// Given that FR is the LHS field being assigned, check if this field is the counter
// for any __counted_by flexible array in the same record. If yes, output both fields.
bool SAGenTestChecker::isAssignmentToCounterField(const FieldRegion *FR,
                                                  const FieldDecl *&CounterFD,
                                                  const FieldDecl *&FAMFD) {
  const FieldDecl *AssignedFD = FR->getDecl();
  if (!AssignedFD)
    return false;

  const IdentifierInfo *AssignedII = AssignedFD->getIdentifier();
  if (!AssignedII)
    return false;

  const RecordDecl *RD = AssignedFD->getParent();
  if (!RD)
    return false;

  // Any flexible-array member in the same record whose __counted_by(...)
  // names the assigned field makes that field the counter of the member.
  for (const FieldDecl *F : RD->fields()) {
    QualType FT = F->getType();
    if (FT.isNull() || !isa<IncompleteArrayType>(FT.getTypePtr()))
      continue;

    const CountedByAttr *A = F->getAttr<CountedByAttr>();
    if (!A)
      continue;

    // Compare the assigned field with the counted_by argument expression:
    // match by resolved FieldDecl, else by identifier spelling.
    const Expr *CountE = A->getCount();
    if (!CountE)
      continue;
    CountE = CountE->IgnoreParenImpCasts();
    const auto *DRE = dyn_cast<DeclRefExpr>(CountE);
    if (!DRE)
      continue;

    const Decl *CountD = DRE->getDecl();
    bool NamesAssigned =
        CountD ? CountD == AssignedFD
               : DRE->getNameInfo().getIdentifier() == AssignedII;
    if (NamesAssigned) {
      CounterFD = AssignedFD;
      FAMFD = F;
      return true;
    }
  }

  return false;
}

